# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `log_call`, one structured loguru record per outside call (a GraphQL request,
# an HTTP fetch, an agent turn, a tool step), timed, with the same shape everywhere.
# Usage: `with log_call("graphql", "startgg", op="PlayerSets", variables=v) as call: ...;
#         call["status"] = 200`. Off by default; an app turns it on with `enable_call_logs()`.
# ---------------------------------------------------------------------------
from __future__ import annotations

import secrets
import time
from collections.abc import Iterator
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Any

from loguru import logger

__all__ = ["CALL_LOGGER", "current_call", "enable_call_logs", "log_call", "log_event", "log_group"]

# Records are emitted from this module, so this is the name to enable / disable them by.
# Disabled on import (loguru's recipe for libraries): a script using ds prints none of them.
CALL_LOGGER = __name__
logger.disable(CALL_LOGGER)

# the group the records being made now belong to (see log_group); follows asyncio tasks and
# asyncio.to_thread like loguru's own context
_group: ContextVar[str | None] = ContextVar("log_group", default=None)
# the record of the log_call block running now (see current_call)
_call: ContextVar[dict[str, Any] | None] = ContextVar("log_call", default=None)


def enable_call_logs() -> None:
    """Let `log_call` records through to the sinks (the app's debug panel adds one)"""
    logger.enable(CALL_LOGGER)


@contextmanager
def log_call(kind: str, source: str, **fields: Any) -> Iterator[dict[str, Any]]:
    """Time a block and log one record about it when it ends

    Args:
        kind: what sort of call: 'graphql', 'http', 'agent', 'tool' (the debug panel formats
            each kind its own way).
        source: who was called, eg 'startgg', 'supermajor', 'smashtube'.
        **fields: known up front, eg op='PlayerSets', variables={...}, url=...

    Yields a dict: put what is only known afterwards in it (status, bytes, ...). The record
    gets `kind`, `source`, the fields, `ms`, and `error` when the block raised (the error is
    re-raised) or the caller set one itself (eg a failure it handles). Session and origin come
    from `logger.contextualize(...)` around the caller.
    """
    call = dict(fields)
    start = time.perf_counter()
    token = _call.set(call)
    try:
        yield call
    except BaseException as e:
        call["error"] = f"{type(e).__name__}: {e}"
        raise
    finally:
        _call.reset(token)
        call["ms"] = round((time.perf_counter() - start) * 1000)
        log_event(kind, source, **call)


def current_call() -> dict[str, Any] | None:
    """The record of the innermost log_call block running now (None outside one), for code that
    is called from inside it without being handed the record, eg an HTTP client's response
    hook. Follows asyncio tasks and asyncio.to_thread, as the session and origin do.
    """
    return _call.get()


@contextmanager
def log_group(name: str) -> Iterator[str]:
    """Give every record made inside one shared `group` field, eg 'player_usage-3f9a1c'

    For one piece of work that makes many calls (a lookup: the tag search, the character
    list, each page), so they can be found together. Inside another group it joins that one:
    the outermost caller names the group. Yields the group's id.
    """
    current = _group.get()
    if current is not None:
        yield current
        return
    token = _group.set(f"{name}-{secrets.token_hex(3)}")
    try:
        yield _group.get() or ""
    finally:
        _group.reset(token)


def log_event(kind: str, source: str, **fields: Any) -> None:
    """One record of the same shape as `log_call`'s, for something not timed

    Eg a tool step read back from an agent turn. ERROR level when `error` is among the fields.
    """
    if (group := _group.get()) is not None:
        fields.setdefault("group", group)
    name = fields.get("op") or fields.get("name") or fields.get("url") or ""
    level = "ERROR" if fields.get("error") else "INFO"
    logger.bind(kind=kind, source=source, **fields).log(level, "{} {} {}", kind, source, name)
